def sorted_pair_sum(premiums, target):
    lo, hi = 0, len(premiums) - 1
    while lo < hi:                      # strict: an account cannot pair with itself
        total = premiums[lo] + premiums[hi]
        if total == target:
            return [lo, hi]
        if total < target:
            lo += 1                     # need more; the largest left is already in
        else:
            hi -= 1                     # need less; the smallest left is already in
    return []

