javascript.solution:
function sortedPairSum(premiums, target) {
  let lo = 0;
  let hi = premiums.length - 1;
  while (lo < hi) {                     // strict: an account cannot pair with itself
    const total = premiums[lo] + premiums[hi];
    if (total === target) return [lo, hi];
    if (total < target) lo++;           // need more; the largest left is already in
    else hi--;                          // need less; the smallest left is already in
  }
  return [];
}
